import{_ as a,C as r,o as n,c as s,a2 as o,E as i}from"./chunks/framework.CGSzHL4z.js";const b=JSON.parse('{"title":"Viewport","description":"","frontmatter":{},"headers":[],"relativePath":"reference/viewport.md","filePath":"reference/viewport.md","lastUpdated":1792713747000}'),l={name:"reference/viewport.md"};function h(d,t,c,g,u,p){const e=r("Screenshot");return n(),s("div",null,[t[0]||(t[0]=o('<h1 id="viewport" tabindex="-1">Viewport <a class="header-anchor" href="#viewport" aria-label="Permalink to &quot;Viewport&quot;">​</a></h1><p>Posing in the 3D view: the gizmo, Resize, pins, IK, onion skin, motion trails and cameras.</p><h3 id="mouse-and-picking" tabindex="-1">Mouse and picking <a class="header-anchor" href="#mouse-and-picking" aria-label="Permalink to &quot;Mouse and picking&quot;">​</a></h3><p>How clicks work in the viewport while a scene is open, and what AcesMotion draws there.</p><h4 id="the-mouse" tabindex="-1">The mouse <a class="header-anchor" href="#the-mouse" aria-label="Permalink to &quot;The mouse&quot;">​</a></h4><ul><li>While a scene is open AcesMotion <strong>holds the viewport mouse</strong> (like Studio&#39;s Animation Editor), so Studio never selects or drags your rig.</li><li>Posing never uses Studio&#39;s Move or Rotate tools: they rewrite a dragged part&#39;s joint.</li><li>Picking one of Studio&#39;s tools hands the mouse back.</li><li>Choosing the Select tool (or no tool), clicking a joint dot, opening a scene, or finishing a viewport pick takes it back.</li></ul><h4 id="picking" tabindex="-1">Picking <a class="header-anchor" href="#picking" aria-label="Permalink to &quot;Picking&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Gesture</th><th>Does</th></tr></thead><tbody><tr><td><strong>Click a body part</strong></td><td>Picks its joint, or the joint it is welded to through any chain of rigid welds (accessories, held tools, Weld, WeldConstraint or RigidConstraint), else the actor&#39;s root.</td></tr><tr><td><strong>Click a joint dot</strong></td><td>Picks that joint. The amber dot on each actor is its <strong>root</strong>.</td></tr><tr><td><strong>Click a skinned rig&#39;s bone</strong></td><td>Picks it, anywhere along it. A click on the mesh away from the bones picks the whole rig (the root).</td></tr><tr><td><kbd>Ctrl</kbd>+click</td><td>Adds or removes a part from the pick.</td></tr><tr><td><strong>Click empty space</strong></td><td>Clears the pick.</td></tr><tr><td><kbd>[</kbd></td><td>Picks the joint above the picked one.</td></tr><tr><td><kbd>]</kbd></td><td>Picks the first joint below.</td></tr><tr><td><kbd>Esc</kbd></td><td>Selects nothing: the picks, keys, blocks, rows and actors. It cancels a gizmo drag first, or drops a picked path point. A click on empty space does the same.</td></tr></tbody></table><ul><li>A part welded to an actor but kept outside it (a sword in Workspace welded to the hand) picks that joint too.</li><li>Welded parts follow their joint as you pose.</li><li>Invisible parts (Transparency 0.99 or more) are never hit, so the invisible root part does not steal clicks.</li><li><strong>Pick welded parts</strong> (Pose menu and Settings &gt; Posing, on by default) off: parts that only reach a joint through welds are skipped, so the click goes to what&#39;s behind them. A shield never blocks the arm.</li><li>Actors without joints (a Sword model, a Cup) keep every part clickable.</li></ul><p>When several things overlap under the pointer, a click goes to them in this order:</p><ol><li>Motion-trail dots and handles.</li><li>A picked camera&#39;s FieldOfView dot.</li><li>The gizmo&#39;s handles.</li><li>The trail line.</li><li>Joint dots.</li><li>Camera frustums.</li><li>Body parts.</li></ol><p>A picked joint highlights its Timeline row, and <kbd>K</kbd> with no row selected keys the picked joints. Clicking a joint&#39;s row picks that joint in place of the viewport&#39;s picks (Ctrl and Shift clicks pick every selected joint row). Picking in the viewport lets go of the selected rows.</p><h4 id="clicking-outside-the-scene" tabindex="-1">Clicking outside the scene <a class="header-anchor" href="#clicking-outside-the-scene" aria-label="Permalink to &quot;Clicking outside the scene&quot;">​</a></h4><p>A click on something outside the scene selects it in Studio the way Studio&#39;s own click would:</p><ul><li>Its outermost model. <strong>Alt+click</strong> selects the part itself.</li><li>Ctrl+click adds or removes.</li><li>Locked parts are skipped, and stand-ins are looked through.</li><li>Parts with CanQuery off (invisible effect holders) are found by their boxes.</li><li>Empty space clears Studio&#39;s selection.</li><li>Studio&#39;s hover outline (in Studio&#39;s own hover colour and line thickness) is drawn on what a click would select. It isn&#39;t drawn over the cast&#39;s own parts, gizmo handles or motion trails, during drags, or in pin mode.</li></ul><h4 id="what-is-drawn" tabindex="-1">What is drawn <a class="header-anchor" href="#what-is-drawn" aria-label="Permalink to &quot;What is drawn&quot;">​</a></h4><ul><li>A grey dot on every joint pivot, and an amber dot on each actor&#39;s root.</li><li>Bones joining the dots (View &gt; Bones): <strong>Diamonds</strong> filled like Blender&#39;s octahedral bones and see-through, <strong>Wire</strong> outlines only, or <strong>Sticks</strong> rounded bars.</li><li>A blue highlight on picked parts and a white one on the hovered part.</li><li>A skinned rig&#39;s bones follow Blender: one bone to the child in line with the joint&#39;s +Y, dashed links to other children, and a tip bone at every chain end.</li><li>A part rig&#39;s bones are only drawn. A click near one is meant for the body part under it.</li><li>Toggles: View &gt; Joint dots, Bones, Part highlights. Colour, thickness, size and transparency of bones and dots: Settings &gt; Gizmos.</li></ul><p><strong>One look for what you drag or follow.</strong> Motion trails, constraint and driver guides, Motion Warp paths, camera frustums, attach lines, a skinned rig&#39;s bone links, the IK pull line and pin stems are all drawn like the posing gizmo&#39;s handles:</p><ul><li>Solid strokes that keep their width on screen as you zoom.</li><li>Drawn again faintly on top, so the stretch hidden behind or inside a part still shows.</li><li>Hovering something you can drag turns it the gizmo&#39;s hover yellow and thicker.</li><li>Lines that only point at something (to a target, a source, a muted camera) stay dashed, at the same width.</li></ul><h4 id="hints-and-readouts" tabindex="-1">Hints and readouts <a class="header-anchor" href="#hints-and-readouts" aria-label="Permalink to &quot;Hints and readouts&quot;">​</a></h4><ul><li>A <strong>hint chip</strong> beside the pointer and the status line (left of the Timeline status bar) say what the current mode does: &quot;Click a spot to pin it there&quot;, &quot;IK: drag an end part&quot;, &quot;Tab · Pivot · Corner&quot;...</li><li>While dragging, a <strong>readout chip</strong> shows the axis (X, Y, Z, YZ, XZ, XY, View, Free) in the axis colour, the angle (&quot;35.0°&quot;) or distance (&quot;0.50 studs&quot;), and the space.</li></ul><h4 id="scene-origin-and-viewport-picks" tabindex="-1">Scene origin and viewport picks <a class="header-anchor" href="#scene-origin-and-viewport-picks" aria-label="Permalink to &quot;Scene origin and viewport picks&quot;">​</a></h4><ul><li>View &gt; Scene origin (or Anchor preview in the Hub) draws the scene origin in the viewport.</li><li><strong>Place origin</strong> and every viewport pick (a part picker&#39;s pick button: Socket, Parent to, Attached to, targets) show what is being picked as a chip in the viewport and a banner in the Hub with a Cancel button.</li><li>Click in the viewport to pick. The click only picks: the selection stays as it was and the Inspector stays on what is picking.</li><li><kbd>Esc</kbd>, a quick <strong>right click</strong> (a right drag still orbits the camera) or the pick button again cancels.</li></ul>',23)),i(e,{name:"tour-viewport",caption:"A joint picked in the viewport, with its rotate rings."}),t[1]||(t[1]=o('<h3 id="posing-gizmo" tabindex="-1">Posing gizmo <a class="header-anchor" href="#posing-gizmo" aria-label="Permalink to &quot;Posing gizmo&quot;">​</a></h3><p>Moves and rotates. One handle set sits at the picked joint (the last picked).</p><h4 id="handles" tabindex="-1">Handles <a class="header-anchor" href="#handles" aria-label="Permalink to &quot;Handles&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Handle</th><th>Does</th></tr></thead><tbody><tr><td><strong>X / Y / Z rings</strong></td><td>Turn about that axis. The front half is bright, the back half faint.</td></tr><tr><td><strong>Outer view ring</strong></td><td>Turns about the view direction.</td></tr><tr><td><strong>Inside the rings</strong></td><td>The trackball turns freely. Another joint&#39;s dot inside them still takes the click, so a nearby joint can be picked.</td></tr><tr><td><strong>X / Y / Z arrows</strong></td><td>Move along the axis.</td></tr><tr><td><strong>Three plane squares</strong> (YZ, XZ, XY)</td><td>Move in a plane. Each sits in the quarter facing the camera.</td></tr><tr><td><strong>Centre dot</strong></td><td>Moves in the view plane.</td></tr></tbody></table><ul><li>Axis colours: X red, Y green, Z blue. The handle under the pointer, and the one you&#39;re dragging, turns yellow.</li><li>The pointer turns into a <strong>rotate cursor</strong> over the rings and the trackball and while turning, and an open hand over the other handles.</li><li>Where handles sit close, the one nearest the pointer takes the click.</li><li>Each handle&#39;s grab band shrinks with a smaller <strong>Gizmo size</strong>, so the rings, the view ring and the trackball stay apart.</li><li>A handle turning edge-on to the view (an arrow pointing at you, a plane square or an axis ring lying along your line of sight) fades out over its last few degrees instead of popping. It gets harder to grab as it fades.</li><li>Once hidden it can&#39;t be grabbed, so an edge-on ring&#39;s line across the middle leaves the clicks to the trackball.</li></ul><h4 id="look-and-size" tabindex="-1">Look and size <a class="header-anchor" href="#look-and-size" aria-label="Permalink to &quot;Look and size&quot;">​</a></h4><ul><li>Drawn like Studio&#39;s own tools: a bright copy in the scene and a faint copy on top, so the part inside the rig still shows.</li><li>Constant size on screen: 84 px radius at Medium.</li><li>Size: Settings &gt; Gizmos &gt; Gizmo size (50 to 200%), or View &gt; Gizmo &gt; Small / Medium / Large (80, 100, 125%).</li><li><strong>Arrow length</strong>: Short (the default) keeps the move arrows just outside the rings, 286 px across at Medium. Long reaches further, 336 px across. Set it in Settings &gt; Gizmos &gt; Arrow length or View &gt; Gizmo &gt; Long arrows.</li></ul><p>Everything else you click or follow in the viewport is drawn the same way: joint dots, the motion trail&#39;s ticks, key dots and tangent knobs, attach target dots, the scene origin and the Resize outlines.</p><ul><li>They&#39;re solid where you can see them, with a see-through copy where something covers them.</li><li>A covered dot stays easy to see (70%), so a joint inside the body can still be picked.</li><li>Lines and outlines show at the gizmo&#39;s strength.</li><li>The scene origin&#39;s axes and the Resize outlines keep their width on screen as you zoom.</li></ul><h4 id="dragging" tabindex="-1">Dragging <a class="header-anchor" href="#dragging" aria-label="Permalink to &quot;Dragging&quot;">​</a></h4><ul><li><strong>A drag moves every picked joint</strong>, each about its own pivot.</li><li>Axis handles turn or move each joint on its own axes in the chosen space. The view ring, trackball and centre dot apply the same change to all.</li><li>A root drag moves the whole actor.</li><li><strong>Space</strong> (Local, Parent, World): Settings &gt; Gizmos, the toolbar Space field, View &gt; Space, or <kbd>R</kbd> to cycle. Studio&#39;s <kbd>Ctrl+L</kbd> (local/world) flips it too.</li><li><strong>Esc</strong> or <strong>right click</strong> cancels the drag and puts the pose back.</li><li>On release, with Auto-key on, the moved tracks are keyed (IK chains and pinned limbs too) in one undo step.</li><li>With Auto-key off the pose stays as a <strong>temporary pose</strong> (no key). Moving the playhead drops an unkeyed pose; <kbd>K</kbd> keys it. Poses are part of undo.</li><li>Keys written by a pose are named after the action in Edit &gt; Undo (&quot;Undo Move&quot;, &quot;Undo Rotate&quot;).</li></ul><h4 id="snapping" tabindex="-1">Snapping <a class="header-anchor" href="#snapping" aria-label="Permalink to &quot;Snapping&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Studio&#39;s increment (Model tab)</th><th>Plain drag</th><th>With <kbd>Ctrl</kbd></th></tr></thead><tbody><tr><td>On (Rotate or Move)</td><td>Steps by it, like Studio&#39;s tools</td><td>Moves freely</td></tr><tr><td>Off</td><td>Free</td><td>Snaps to 15 degrees or 1 stud</td></tr></tbody></table><ul><li>The status line says &quot;Ctrl moves freely&quot; or &quot;Ctrl snaps&quot;.</li><li>Constraint guide handles snap the same way: a Motion Warp&#39;s Arc turn diamond, Limit Rotation&#39;s arcs and radii, and the other angle and length handles on the guides.</li><li>They snap to whole multiples (a limit lands on 45 degrees, not 45 from where you grabbed), and <strong>Ctrl</strong> flips it.</li></ul><p><strong>Rotate ruler</strong>: while you turn a ring (X, Y, Z, the outer view ring or a Track To&#39;s Roll ring), ticks show round it from where the drag started, like Studio&#39;s own rotate tool.</p><ul><li>One tick per snap step, at least 5 degrees apart. With free rotation, only every 45 degrees.</li><li>Ticks are longer at every 45 degrees and longest at every 90. Ticks on the ring&#39;s far side are faint.</li><li>The angle turned so far is filled: a translucent pie from where the drag started.</li><li>A bold pointer shows where it points now.</li><li>The readout goes back to 0 after a whole turn: turning 370 degrees reads 10.</li></ul><h4 id="keys-during-a-drag" tabindex="-1">Keys during a drag <a class="header-anchor" href="#keys-during-a-drag" aria-label="Permalink to &quot;Keys during a drag&quot;">​</a></h4><p>The status line lists these while you drag.</p><table tabindex="0"><thead><tr><th>Key</th><th>Does</th></tr></thead><tbody><tr><td><strong>Type a number</strong></td><td>On an arrow or a ring, sets an exact amount (degrees round a ring, studs along an arrow). It takes over from the mouse at once.</td></tr><tr><td><kbd>-</kbd></td><td>Flips the typed number&#39;s sign.</td></tr><tr><td><kbd>Backspace</kbd></td><td>Edits it. Empty gives the mouse back.</td></tr><tr><td><kbd>Enter</kbd></td><td>Keeps the drag.</td></tr><tr><td><kbd>X</kbd>, <kbd>Y</kbd> or <kbd>Z</kbd></td><td>Puts the drag on that axis from where it began (a move along it, a rotation round it, in the current Space). The same key again goes back to the handle you grabbed.</td></tr><tr><td>Hold <kbd>Shift</kbd></td><td>A fine drag: each bit of mouse movement turns or moves it a tenth as far, with snapping off while it&#39;s held.</td></tr></tbody></table><ul><li>On a square, the centre dot or the trackball, lock an axis first, then type.</li><li>Going round a ring with <kbd>Shift</kbd> still turns it the same way. Let go of <kbd>Shift</kbd> and it carries on at full speed from there.</li></ul><h4 id="handle-groups" tabindex="-1">Handle groups <a class="header-anchor" href="#handle-groups" aria-label="Permalink to &quot;Handle groups&quot;">​</a></h4><ul><li><strong>View &gt; Gizmo</strong> turns handle groups on or off: Rotate rings, Move arrows, Plane handles.</li><li><strong>Separate move and rotate</strong> shows only the rotate handles or only the move handles (the arrows move in to the centre). <kbd>T</kbd> switches the tool.</li></ul><h4 id="posing-what-a-constraint-drives" tabindex="-1">Posing what a constraint drives <a class="header-anchor" href="#posing-what-a-constraint-drives" aria-label="Permalink to &quot;Posing what a constraint drives&quot;">​</a></h4><ul><li>Posing something a constraint drives edits its keys underneath, and the viewport shows the result: dolly a tracking camera and it keeps aiming.</li><li>What the constraints take over at full strength greys out on the gizmo (the rings under a Track To, the arrows under a Copy Location).</li><li>A chip at the top of the viewport says so: &quot;Rotation driven by Track To&quot;.</li><li>A Track To adds a blue <strong>Roll</strong> ring around its aim. Drag it to tilt the camera while it tracks: one undo step, keyed at the playhead when Roll has keys.</li></ul><h4 id="constraint-guides" tabindex="-1">Constraint guides <a class="header-anchor" href="#constraint-guides" aria-label="Permalink to &quot;Constraint guides&quot;">​</a></h4><p>Select a constraint block on the Timeline (several at once show each one&#39;s) and its guide draws in the viewport, wherever the playhead is.</p><table tabindex="0"><thead><tr><th>Constraint</th><th>Guide</th></tr></thead><tbody><tr><td>Track, Copy and Delay ones</td><td>A dashed line to a ring on its target, in the target&#39;s colour.</td></tr><tr><td>Track family and Face Motion</td><td>Aim and up ticks labelled with their axes (&quot;Aim -Z&quot;, &quot;Up +Y&quot;).</td></tr><tr><td>Limit Location</td><td>The box it keeps it in. Its edges behind it are dashed, the dots on its far faces dimmer.</td></tr><tr><td>Limit Rotation</td><td>A filled wedge per axis it limits, with its range (&quot;Z -45 to 45&quot;).</td></tr><tr><td>Limit Distance</td><td>The sphere around its target.</td></tr><tr><td>Floor</td><td>A patch of its plane with its offset.</td></tr><tr><td>A distance fade</td><td>The Full within ring (filled) and the None beyond ring (dashed) with their values, plus a line to the subject showing how far it is and how strong the constraint is there (&quot;8.9 studs 61%&quot;).</td></tr></tbody></table><ul><li>The status line names the pick and what its guide does (&quot;Crate picked | Limit Distance: drag the square to set the distance&quot;).</li><li>Hovering or dragging a handle rings it in yellow.</li><li><strong>View &gt; Show all constraint guides</strong> (or Settings &gt; Posing) also draws every constraint under the playhead.</li><li>While a selected constraint shows, the move, rotate and resize gizmo hides, so only its handles take drags.</li><li>Clicking a part or empty space in the viewport, or <kbd>Esc</kbd>, lets the constraint go and brings the gizmo back.</li></ul><p><strong>Drag a guide&#39;s handle</strong> to change its setting live:</p><ul><li>A Limit Distance&#39;s radius (the white square), a Limit Location face, a Limit Rotation arc&#39;s ends, a Floor&#39;s height, a distance fade&#39;s Full within and None beyond rings.</li><li>Hover a handle and it lights up, with a card saying what it does after the tooltip delay.</li><li>While dragging, a faint ghost shows where it started and the readout chip shows the value and the change (&quot;Distance 6.5 studs (+2.5)&quot;).</li><li>One undo step on release, keyed at the playhead when the setting has keys. <kbd>Esc</kbd> or right click cancels.</li></ul><p><strong>Point targets</strong> draw a small cross with the point&#39;s X Y Z beside it and a dashed line from the subject.</p><ul><li>Click it (or the Inspector&#39;s <strong>Move in viewport</strong>, or the block menu&#39;s <strong>Move point</strong>) and the gizmo&#39;s move arrows move the point.</li><li>One undo step per drag, keyed when it has keys.</li><li><kbd>Esc</kbd> or a click anywhere else ends it.</li></ul><h4 id="driver-guides" tabindex="-1">Driver guides <a class="header-anchor" href="#driver-guides" aria-label="Permalink to &quot;Driver guides&quot;">​</a></h4><p>Select a driver block on the Timeline (or turn on Show all constraint guides for every one under the playhead). The viewport shows what it reads, in the driver colour:</p><ul><li>A dot on what it drives, a dashed line to its source with a ringed dot on it, and a chip with the live numbers (&quot;r2 · 23.4 studs &gt; FieldOfView 52&quot;).</li></ul><table tabindex="0"><thead><tr><th>Driver</th><th>Adds</th></tr></thead><tbody><tr><td><strong>Distance</strong> with a From</td><td>Its line runs between the two things it measures.</td></tr><tr><td><strong>Axis</strong></td><td>An arrow along the axis it reads, with its name (&quot;Y&quot;). For a world position, a dotted bracket from where the axis reads 0 up to the dot, with a tick (&quot;r2 · Position Y 1.6 studs &gt; Rot Z 12°&quot;).</td></tr><tr><td><strong>Speed</strong></td><td>An arrow along the way its source is moving.</td></tr><tr><td><strong>Property</strong> and <strong>Copy</strong></td><td>The line to their object (&quot;Hero.Power 0.75 &gt; Brightness 1.8&quot;, &quot;Copy · Lamp.Brightness &gt; Brightness&quot;).</td></tr><tr><td>A custom driver</td><td>A line to each thing it reads.</td></tr></tbody></table><ul><li>The status line says what the guide means (&quot;Cam picked | Distance: the dashed line is the measure it reads&quot;).</li><li>Driver guides have no handles: edit in the Inspector.</li><li>While one shows, the gizmo hides as for constraints.</li></ul><h4 id="motion-warp-guide" tabindex="-1">Motion Warp guide <a class="header-anchor" href="#motion-warp-guide" aria-label="Permalink to &quot;Motion Warp guide&quot;">​</a></h4><p>Select a Motion Warp on the Timeline. The viewport shows:</p><ul><li>A dashed line from where it starts to its target, and a ring on the target.</li><li>The path it plays now, as a solid orchid tube drawn like the gizmo&#39;s handles (faint where something covers it).</li><li>A white <strong>diamond</strong> at the curve&#39;s highest point. Click it for its <strong>curve gizmo</strong>, drawn like the posing gizmo in orchid.</li></ul><table tabindex="0"><thead><tr><th>Handle</th><th>Sets</th><th>What happens</th></tr></thead><tbody><tr><td>The <strong>arrow</strong> (pointing the way the curve bends off the line)</td><td><strong>Arc</strong></td><td>Out for a taller curve, in for a flatter one, stopping at the line. The chip reads &quot;Arc 1.4 · Turn 15°&quot;.</td></tr><tr><td>The <strong>diamond</strong>, dragged along the orbit track</td><td><strong>Arc turn</strong></td><td>The curve&#39;s top follows the pointer round the line. The chip reads &quot;Arc turn 95° (+40)&quot;, and a faint dot marks where it started.</td></tr></tbody></table><ul><li>The <strong>orbit track</strong> is a thin orchid circle round the line through the curve&#39;s top: every place the top can swing to.</li><li>Arc steps by 0.1 while Studio&#39;s Move increment is on and moves freely while it&#39;s off. <kbd>Ctrl</kbd> flips it, as for every move.</li><li>Each drag is one undo step and the gizmo stays for the next. Hover turns a handle yellow.</li><li><kbd>Esc</kbd> or a click elsewhere lets it go.</li><li>With Bends Joints the guide follows the reaching joint&#39;s path.</li><li>A straight path has nothing to bend, so no diamond.</li><li>While you drag that actor&#39;s keys or pose it, the path follows with fewer points (a little less smooth). It&#39;s drawn exactly again a moment after you stop.</li><li>An actor that rides something (an Attach key) has its path drawn where it really flies, riding it, and its By speed trip measured from there too.</li></ul><h4 id="tool-indicator" tabindex="-1">Tool indicator <a class="header-anchor" href="#tool-indicator" aria-label="Permalink to &quot;Tool indicator&quot;">​</a></h4><p>A small pill in the viewport&#39;s bottom-left corner names the posing tool while a scene is open, so you can see at a glance which handles a drag will use. It&#39;s always the lowest chip there: the version compare chip and the chip saying who is viewing you stack above it.</p><table tabindex="0"><thead><tr><th>It reads</th><th>When</th></tr></thead><tbody><tr><td><strong>Move &amp; Rotate</strong></td><td>The one gizmo with rings and arrows.</td></tr><tr><td><strong>Move, Rotate</strong></td><td>Separate move and rotate handles are on.</td></tr><tr><td><strong>Resize</strong> (blue icon)</td><td>The Resize tool.</td></tr><tr><td><strong>Resize</strong> with the reason, amber</td><td>The Resize tool, but nothing picked can resize, for example &quot;Bones can&#39;t resize in Roblox. Move the next bone to stretch the limb.&quot;</td></tr><tr><td>&quot;Studio Scale tool. Posing paused.&quot;, amber, with <strong>Back to posing</strong></td><td>Studio&#39;s own Move, Rotate, Scale or Transform tool has the mouse, so AcesMotion&#39;s gizmo can&#39;t take clicks.</td></tr></tbody></table><ul><li>Click it to switch tools, the same as <kbd>T</kbd>. While Studio&#39;s tool has the mouse, a click (or <strong>Back to posing</strong>) picks Studio&#39;s Select tool and posing takes the mouse back.</li><li>Right-click it for Move &amp; rotate handles, Resize handles, Separate handles, Corner handles, Resize applies to (Each, Group) and <strong>Hide tool indicator</strong>.</li><li>Turn it off or on with <strong>Hide tool indicator</strong>, View &gt; Tool indicator or Settings &gt; Posing &gt; Show tool indicator. It only shows on your screen.</li></ul>',46)),i(e,{name:"first-pose",caption:"Posing a shoulder with the gizmo."}),t[2]||(t[2]=o('<h3 id="resize-tool" tabindex="-1">Resize tool <a class="header-anchor" href="#resize-tool" aria-label="Permalink to &quot;Resize tool&quot;">​</a></h3><p>Resizes <strong>Part and Model actors</strong> and <strong>limbs</strong> of a rig. Turn it on with the toolbar <strong>Resize</strong> button, View &gt; Gizmo &gt; Resize handles, or <kbd>T</kbd>. With nothing it can resize picked, there are no handles, clicks still pick, and the status bar says why (&quot;Resize works on parts, models and limbs.&quot;).</p><h4 id="handles-1" tabindex="-1">Handles <a class="header-anchor" href="#handles-1" aria-label="Permalink to &quot;Handles&quot;">​</a></h4><ul><li>A coloured shaft with a ball standing off each of the six faces: X red, Y green, Z blue. Yellow on hover and while dragging.</li><li>One white <strong>corner cube</strong> at the corner nearest the pointer, on the side facing the camera. It follows the pointer around that side, and hides under 24 px on screen or with the camera inside.</li><li>A blue outline around the part.</li><li>Settings &gt; Posing &gt; Corner handles (or View &gt; Gizmo &gt; Corner handles) hides the corners.</li></ul><h4 id="dragging-1" tabindex="-1">Dragging <a class="header-anchor" href="#dragging-1" aria-label="Permalink to &quot;Dragging&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Gesture</th><th>Does</th></tr></thead><tbody><tr><td>Drag a face handle</td><td>That side moves and the opposite side stays. Sizes step in Studio&#39;s Move increment and never go below 0.05.</td></tr><tr><td>Drag a corner</td><td>The two sides you see change. The opposite corner stays (a ring marks it) and a faint box shows the start size.</td></tr><tr><td><kbd>Ctrl</kbd></td><td>Resizes both sides, about the centre.</td></tr><tr><td><kbd>Alt</kbd></td><td>Keeps the proportions.</td></tr><tr><td><kbd>Esc</kbd></td><td>Cancels.</td></tr></tbody></table><ul><li>For a <strong>Model</strong> actor every handle keeps proportions, Ctrl does nothing, and <strong>Scale</strong> is keyed.</li><li>The readout reads &quot;Size 4 × 2.5 × 2 (+0.5)&quot;, or &quot;(+25%)&quot; for a Model or a Group.</li><li>On release, with Auto-key on, the change keys <strong>Size</strong> (parts) or <strong>Scale</strong> (models) plus the root, frame 0 included. Otherwise it&#39;s a temporary pose.</li><li>It&#39;s one undo step (&quot;Undo Resize&quot;).</li><li>Space and Pivot are disabled while Resize is the tool.</li><li>Onion ghosts of a resized actor show the size keyed at their own time.</li></ul><h4 id="limbs" tabindex="-1">Limbs <a class="header-anchor" href="#limbs" aria-label="Permalink to &quot;Limbs&quot;">​</a></h4><p>Pick a limb (the dot of a joint that moves a part) and drag a handle to resize it.</p><ul><li>The limb grows away from the joint it hangs from. A ring marks that joint, before and during the drag.</li><li>The joints inside it move out with it, so a longer upper arm carries the forearm and hand down. They keep their own size: to make a big fist, resize the hand.</li><li>Hats, hair and anything else attached or welded to the part move out with it and keep their size, WeldConstraints included.</li><li>Locks, motion trails and warp guides use the scaled limb, so a Lock on a longer arm reaches with the longer arm.</li><li>Only <strong>Size</strong> is keyed (<code>prop:LeftUpperArm.Size</code>), never the root. The joint keeps the limb attached, and the rig&#39;s C0 and C1 are never changed.</li><li>Alt keeps proportions. Ctrl does nothing here: the joint always stays put.</li><li>Several limbs resize <strong>Each</strong>. Group falls back to Each, since two hands have no one joint to grow from.</li><li><strong>Flip pose</strong> swaps limb sizes along with the pose, so a big left fist becomes a big right fist.</li><li>Bones can&#39;t resize (Roblox gives a bone no size). Move the next bone along to stretch a skinned limb instead.</li><li>A rig&#39;s root can&#39;t resize either: pick a limb.</li><li>In games the runtime plays limb sizes. A Roblox animation can&#39;t hold them, so native export names them and asks you to mute them. A Humanoid doesn&#39;t refit its HipHeight, so longer legs sink into the floor unless the game adjusts it.</li></ul><h4 id="several-actors" tabindex="-1">Several actors <a class="header-anchor" href="#several-actors" aria-label="Permalink to &quot;Several actors&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Mode</th><th>What it does</th></tr></thead><tbody><tr><td><strong>Each</strong></td><td>Grows every picked actor&#39;s side facing the handle&#39;s way in the world by the same amount. A turned crate does not make an L.</td></tr><tr><td><strong>Group</strong></td><td>Scales them together as one block, gaps included. Always in proportion; Ctrl scales about the block&#39;s centre.</td></tr></tbody></table><ul><li>Set it with the toolbar <code>Resize: Each</code> field, the Resize options chevron, or Settings &gt; Posing &gt; Several actors.</li><li>With several picked, the handles sit on one blue box around them all, and each actor gets a thin outline.</li><li>While dragging, a dashed grey box shows where it started.</li></ul><div class="warning custom-block"><p class="custom-block-title">What can&#39;t be resized</p><p>While every picked or selected thing is a camera, a bone or a rig&#39;s root:</p><ul><li>The Resize button (and View &gt; Gizmo &gt; Resize handles) is greyed with the reason, for example &quot;Cameras can&#39;t be resized. Drag the blue dot to change FieldOfView.&quot;</li><li><kbd>T</kbd> skips Resize.</li><li>Picking one while Resize is already the tool keeps Resize. The tool indicator turns amber with the reason, and the status bar says it too.</li></ul></div><h3 id="camera-actors" tabindex="-1">Camera actors <a class="header-anchor" href="#camera-actors" aria-label="Permalink to &quot;Camera actors&quot;">​</a></h3><p>How camera actors draw in the viewport, and how you pick, pose and aim them.</p><h4 id="frustums" tabindex="-1">Frustums <a class="header-anchor" href="#frustums" aria-label="Permalink to &quot;Frustums&quot;">​</a></h4><ul><li>Every camera actor draws a wire frustum in its actor tint: a small body box behind the lens, four edges to a far rectangle, and a filled <strong>up triangle</strong> on the far rectangle&#39;s top edge so roll reads.</li><li>The far rectangle sits at the <strong>Frustum length</strong> (Settings, 1 to 20 studs, <strong>4</strong> by default), sized by the camera&#39;s live FieldOfView and the viewport&#39;s aspect.</li><li>It follows the camera while scrubbing and playing.</li><li><strong>Show frustums</strong>: All cameras, Selected only, Off.</li><li>The camera the view is locked on while looking through it draws no frustum. While looking away every frustum draws.</li></ul><table tabindex="0"><thead><tr><th>State</th><th>Looks like</th></tr></thead><tbody><tr><td>Idle</td><td>Tint edges.</td></tr><tr><td><strong>Hover</strong></td><td>Thicker edges in the gizmo&#39;s hover yellow.</td></tr><tr><td><strong>Selected</strong></td><td>Thicker accent edges and fills.</td></tr><tr><td><strong>Live</strong></td><td>The camera the Camera track picks at the playhead: thicker and more filled.</td></tr><tr><td><strong>Muted</strong> actor</td><td>Dashed, 40%.</td></tr></tbody></table><ul><li>Selected wins over Hover, Hover over Live.</li><li>The edges are solid strokes like the gizmo&#39;s, faint where a part covers them.</li></ul><p><strong>Name chip</strong>: the role and a camera icon in the actor&#39;s tint, over the camera body.</p><ul><li>It shows on hover, when picked and while live (with the <strong>Live</strong> pill beside it while live).</li><li>It moves up while the gizmo is on that camera, so it clears the rings.</li><li>A muted camera shows it only when picked.</li></ul><h4 id="picking-and-posing" tabindex="-1">Picking and posing <a class="header-anchor" href="#picking-and-posing" aria-label="Permalink to &quot;Picking and posing&quot;">​</a></h4><ul><li>Click one of its edges (within 6 px), its body or its name chip.</li><li>The inside of the far rectangle does not pick, so a camera never blocks clicking what is behind it.</li><li>Ctrl+click adds or removes it, as for any actor.</li><li>The posing gizmo then moves and rotates the camera&#39;s root like any actor&#39;s root. Every drag is one undo step, keyed with Auto-key.</li><li><strong>No gizmo on the camera you look through.</strong> While the view is locked on a camera (look-through on, not looking away), that camera&#39;s gizmo and handles are hidden, like its frustum, so nothing sits in the eye. Look away (move the view while paused) or leave look-through to pose it again.</li><li>Status line: &quot;CloseUp picked | move and rotate it like any actor | drag the blue dot to change FieldOfView&quot;.</li></ul><h4 id="fieldofview-handle" tabindex="-1">FieldOfView handle <a class="header-anchor" href="#fieldofview-handle" aria-label="Permalink to &quot;FieldOfView handle&quot;">​</a></h4><p>One picked camera shows a blue dot (the Resize tool&#39;s Z face ball) at the far rectangle&#39;s centre, with a dashed look axis from the lens. It shows with every tool; cameras cannot be resized (see Resize tool). Hover reads &quot;FieldOfView 35°. Drag to change.&quot;</p><ul><li><strong>Drag it along the look axis</strong>: pull out for a longer lens (narrower view), push in for a wider one.</li><li>Steps of 0.5°, <strong>Shift</strong> 0.1°, <strong>Ctrl</strong> whole degrees. Clamped to 1 to 120.</li><li>A readout &quot;FOV 24° was 35°&quot; follows the pointer, and the old frustum stays at 35% as a ghost.</li><li>While dragging the status line reads &quot;Dragging FieldOfView of CloseUp | Ctrl whole degrees, Shift finer | Esc cancels&quot;.</li><li><strong>Esc</strong> or right click cancels.</li><li>Release is one undo step &quot;Set FieldOfView of CloseUp&quot;, by the property rule: keyed at the playhead with Auto-key on (a FieldOfView track), a temporary pose with it off, or the camera&#39;s own value when it has no FieldOfView track.</li><li>Hidden with several cameras picked (use the Inspector).</li></ul><h4 id="rotation" tabindex="-1">Rotation <a class="header-anchor" href="#rotation" aria-label="Permalink to &quot;Rotation&quot;">​</a></h4><ul><li><strong>Rotation keys keep the horizon level.</strong> A new camera root track turns in <strong>YXZ</strong> order (yaw, then pitch, then roll), so turning a camera between two keys adds no roll.</li><li>Tracks made before this used XYZ and roll between keys that change both yaw and pitch. Right click the camera&#39;s root row &gt; Rotation &gt; Euler YXZ converts one.</li><li>A camera&#39;s root turns each angle on its own curve between keys, where a joint takes the shortest turn, because the short way would roll the camera.</li><li><strong>Cameras turn like a camera head (pan, tilt, roll).</strong> Rotating a camera with the gizmo pans and tilts it without rolling it, whichever ring or space you use.</li><li>Only a turn about the camera&#39;s own look axis (the Z ring in Local space, the roll ring) rolls it.</li><li>Its keys always store the tilt between -90 and 90 degrees, with pan and roll counting on through whole turns. So a pan or a full orbit plays smoothly between keys and never tumbles or flips. (On a YXZ camera track; older XYZ camera tracks convert with right click &gt; Rotation &gt; Euler YXZ.)</li><li><strong>Cameras measure from the scene origin.</strong> A camera&#39;s keys always count from the scene origin, also in a scene whose actors measure from their own root parts (a camera has no root part). Games always played them that way.</li></ul><h4 id="focus-on-the-pointer" tabindex="-1">Focus on the pointer <a class="header-anchor" href="#focus-on-the-pointer" aria-label="Permalink to &quot;Focus on the pointer&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Key</th><th>Does</th></tr></thead><tbody><tr><td><kbd>F</kbd></td><td>The camera turns to look at the first visible surface under the pointer. It keeps its position and its <strong>roll</strong> (only yaw and pitch change, in YXZ order).</td></tr><tr><td><kbd>Ctrl+F</kbd></td><td>Focus and level: the same, and the roll goes to 0 whatever the &quot;Reset roll when focusing&quot; setting says.</td></tr></tbody></table><ul><li><kbd>F</kbd> works with a camera picked and the Move or Rotate gizmo on it, or a camera actor selected in the Timeline or Hub. Point at anything in the viewport and press it.</li><li><strong>Reset roll when focusing</strong> (Settings &gt; Camera and the camera menu, off by default) makes <kbd>F</kbd> level it instead.</li><li>It&#39;s a posing action: one undo step &quot;Focus CloseUp&quot;, keyed at the playhead with Auto-key on, else a temporary pose (K keys it; moving the playhead drops it).</li><li>Camera frustums, onion ghosts and invisible parts are looked through.</li><li>Refused with a status line reason when nothing is under the pointer, the camera or its root track is locked, or the scene is read-only.</li><li>With no camera picked <kbd>F</kbd> does nothing (Studio&#39;s own <kbd>F</kbd> zooms as usual).</li><li>While <kbd>F</kbd> acts, Studio&#39;s view is held still for half a second, so Studio&#39;s own <kbd>F</kbd> (Zoom to) cannot also move it.</li><li>Ignored while a mouse button is held.</li><li>Not while looking through that camera (its gizmo is hidden), except while piloting it: then <kbd>F</kbd> turns the piloted camera.</li><li>While looking through a camera, both keys work only when <strong>Pilot camera</strong> is on (on the piloted camera). Attached without Pilot they do nothing.</li><li>Both are rebindable in Settings &gt; Shortcuts (Ctrl+F is &quot;Focus camera and level it&quot;). Reset this group on the Camera page puts both back.</li></ul>',32)),i(e,{name:"vp-cameras",caption:"Two camera actors: the live one labelled, each with its frustum."}),t[3]||(t[3]=o('<h3 id="pins" tabindex="-1">Pins <a class="header-anchor" href="#pins" aria-label="Permalink to &quot;Pins&quot;">​</a></h3><p>A pinned part keeps its place while you pose: the limb above it bends (or aims) to reach it.</p><h4 id="pinning" tabindex="-1">Pinning <a class="header-anchor" href="#pinning" aria-label="Permalink to &quot;Pinning&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Gesture</th><th>Does</th></tr></thead><tbody><tr><td>Hold <kbd>P</kbd> and click a part</td><td>Pins it at that spot: a <strong>point pin</strong>. Only that spot is held, and the pin marker sits on it.</td></tr><tr><td>Hold <kbd>P</kbd> and click a joint dot</td><td>Pins the whole part.</td></tr><tr><td><kbd>P</kbd>-click a pinned part</td><td>Unpins it.</td></tr><tr><td><strong>Tap</strong> <kbd>P</kbd> (under 0.35 s, no click)</td><td>Pins the picked parts, or unpins them when all are pinned already.</td></tr><tr><td><kbd>Shift+P</kbd></td><td>Removes pins.</td></tr></tbody></table><ul><li>The toolbar <strong>Pin</strong> button and Pins menu &gt; &quot;Pin or unpin picked parts&quot; do the same as a tap.</li><li>Pins menu &gt; Clear all pins, or a joint row&#39;s pin icon, also removes pins.</li><li>A root cannot be pinned.</li><li>Pins live in the session (cleared when another scene opens). Each pin action is one undo step.</li><li>A faint line shows any gap a pinned limb cannot close.</li><li>A pinned end of a solved limb keeps its world rotation.</li></ul><h4 id="anchored-pins" tabindex="-1">Anchored pins <a class="header-anchor" href="#anchored-pins" aria-label="Permalink to &quot;Anchored pins&quot;">​</a></h4><ul><li>With parts picked, <strong>hold <kbd>P</kbd> and click a floor or prop</strong> (or <kbd>Alt</kbd>+<kbd>P</kbd>-click a body part) to anchor their pins to it.</li><li>They ride with it. Move the prop with Studio&#39;s tools or a script and the pinned limb follows: one undo step &quot;Follow anchored pins&quot;, keyed with Auto-key.</li><li>Drag a prop actor with the gizmo and the limb follows in the same drag.</li><li>A pin never anchors to its own body.</li><li>Scrubbing does not re-solve other frames.</li></ul><h4 id="turning-pins-into-locks" tabindex="-1">Turning pins into locks <a class="header-anchor" href="#turning-pins-into-locks" aria-label="Permalink to &quot;Turning pins into locks&quot;">​</a></h4><p><strong>Turn pins into locks</strong> (Pins menu, or the viewport&#39;s right click on empty space) keeps a pinned pose holding while it plays. Each pin becomes a Lock from the playhead to its row&#39;s next key, then the pins go.</p><h4 id="markers" tabindex="-1">Markers <a class="header-anchor" href="#markers" aria-label="Permalink to &quot;Markers&quot;">​</a></h4><ul><li>A badge with the pin icon on a stem above a ring. An anchored pin has a link icon.</li><li>While <kbd>P</kbd> is held a ghost marker follows the pointer. It&#39;s red with an x over a pinned part.</li><li>The toolbar badge counts pins. The status line counts pins and anchored pins.</li></ul>',11)),i(e,{name:"basics-posing",caption:"The hips posed while a foot is pinned."}),t[4]||(t[4]=o('<h3 id="ik-and-fk" tabindex="-1">IK and FK <a class="header-anchor" href="#ik-and-fk" aria-label="Permalink to &quot;IK and FK&quot;">​</a></h3><p><strong>FK or IK</strong> is one switch: the toolbar&#39;s FK | IK, the IK options menu, Settings &gt; Posing &gt; IK posing, or <kbd>X</kbd> in the viewport.</p><h4 id="switching" tabindex="-1">Switching <a class="header-anchor" href="#switching" aria-label="Permalink to &quot;Switching&quot;">​</a></h4><ul><li><kbd>X</kbd> switches, and it stays until you press it again (outside a drag; mid drag <kbd>X</kbd> still locks the X axis).</li><li>For a moment after <kbd>X</kbd> the hint chip says which: &quot;IK: drag an end part&quot; / &quot;FK: drag to rotate one joint&quot;.</li></ul><h4 id="dragging-in-ik" tabindex="-1">Dragging in IK <a class="header-anchor" href="#dragging-in-ik" aria-label="Permalink to &quot;Dragging in IK&quot;">​</a></h4><ul><li><strong>Press a non-root part and drag</strong>: it is picked and a view-plane drag bends its chain toward the pointer.</li><li>A click without a drag just picks it.</li><li>A soft tube shows the chain and a dashed line the pull.</li><li>A joint that hangs from the root part (an R15 LowerTorso, an R6 Torso) just moves in IK.</li><li>A one-joint chain (an R6 limb) can only turn: it aims its part&#39;s far end at the pointer.</li><li><strong>Swing</strong>: dragging an elbow or knee swings the limb about its upper-to-end line toward the pointer. The hand or foot stays put and keeps its rotation.</li></ul><h4 id="chain-length" tabindex="-1">Chain length <a class="header-anchor" href="#chain-length" aria-label="Permalink to &quot;Chain length&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Value</th><th>Chain</th></tr></thead><tbody><tr><td><strong>Auto</strong></td><td>Up to the nearest pin, a branch point or 3 joints.</td></tr><tr><td>1 to 8</td><td>Goes on through branch points, never past a pin.</td></tr></tbody></table><ul><li>No length takes the rig&#39;s root joint, so an R6 arm or leg turns on its own at any length instead of swinging the body.</li><li>Set it with the toolbar Chain field and menu, <kbd>Ctrl+[</kbd> (shorter), <kbd>Ctrl+]</kbd> (longer), or Settings &gt; Posing &gt; Default IK chain length.</li><li>It can change mid-drag.</li></ul><h4 id="joint-limits" tabindex="-1">Joint limits <a class="header-anchor" href="#joint-limits" aria-label="Permalink to &quot;Joint limits&quot;">​</a></h4><p><strong>Limbs bend like real elbows and knees.</strong> The rig&#39;s own HingeConstraint or BallSocketConstraint (cone 30 degrees or less plus twist limits) between a joint&#39;s two parts is its limit.</p><ul><li>The middle joint bends only about that axis, to the side and within the range its twist limits allow (widened to include the rest pose).</li><li>Without a constraint it keeps the current bend, or bends like a knee/elbow by name.</li><li>At a limit the end stops short.</li></ul><div class="info custom-block"><p class="custom-block-title">Not yet</p><p>Only elbows and knees are limited today; other joints are not clamped. &quot;Pole target&quot; is not available.</p></div><h3 id="temporary-pivot" tabindex="-1">Temporary pivot <a class="header-anchor" href="#temporary-pivot" aria-label="Permalink to &quot;Temporary pivot&quot;">​</a></h3><p><strong>Hold <kbd>Tab</kbd></strong> over a part (with a joint picked) to turn about a point other than the joint.</p><h4 id="where-the-pivot-drops" tabindex="-1">Where the pivot drops <a class="header-anchor" href="#where-the-pivot-drops" aria-label="Permalink to &quot;Where the pivot drops&quot;">​</a></h4><p>The pivot drops at the pointer and locks there while held.</p><table tabindex="0"><thead><tr><th>Under the pointer</th><th>Pivot</th><th>Chip label</th></tr></thead><tbody><tr><td>A joint dot</td><td>The joint</td><td>&quot;Joint&quot;</td></tr><tr><td>The first visible surface (any part, the floor included)</td><td>The nearest corner, edge midpoint, face centre or centre of that part</td><td>&quot;Corner&quot;, &quot;Edge&quot;, &quot;Face&quot;, &quot;Centre&quot;</td></tr><tr><td>A surface, with <strong>Snap pivot</strong> off</td><td>The exact surface point, with a fainter marker and no snap dots</td><td></td></tr></tbody></table><ul><li>The chip reads &quot;Tab · Pivot · Corner&quot;.</li><li>The Pivot field reads &quot;Pivot: Custom&quot;.</li><li>The status line says &quot;Turning about the pivot. Release Tab to go back.&quot;</li></ul><h4 id="while-held" tabindex="-1">While held <a class="header-anchor" href="#while-held" aria-label="Permalink to &quot;While held&quot;">​</a></h4><p>The gizmo sits on the pivot and every picked target turns about it.</p><table tabindex="0"><thead><tr><th>Target</th><th>Turns how</th></tr></thead><tbody><tr><td><strong>FK</strong></td><td>Turns the joint about the point, so the joint slides.</td></tr><tr><td><strong>IK</strong></td><td>Turns the part about the point and bends the chain to keep it joined.</td></tr><tr><td>A root</td><td>Turns the whole actor.</td></tr><tr><td>Move handles</td><td>Just sit there.</td></tr></tbody></table><h4 id="releasing" tabindex="-1">Releasing <a class="header-anchor" href="#releasing" aria-label="Permalink to &quot;Releasing&quot;">​</a></h4><ul><li><strong>Release <kbd>Tab</kbd></strong> and the gizmo goes back to the joint.</li><li>Releasing mid-drag finishes that drag about the pivot, then it goes back.</li><li>The pivot rides with its part, is not saved and is not its own undo step.</li></ul><h4 id="settings" tabindex="-1">Settings <a class="header-anchor" href="#settings" aria-label="Permalink to &quot;Settings&quot;">​</a></h4><ul><li>Snap pivot: Pivot field menu, View &gt; Gizmo &gt; Snap pivot, Settings &gt; Posing.</li><li>The key is rebindable (Settings &gt; Posing &gt; Temporary pivot key).</li></ul><div class="tip custom-block"><p class="custom-block-title">Tab doesn&#39;t work?</p><p>If Studio or another plugin owns the key on your machine, rebind it.</p></div>',27)),i(e,{name:"fig-pivot-held",caption:"A temporary pivot held while rotating."}),t[5]||(t[5]=o('<h3 id="right-click-menu" tabindex="-1">Right-click menu <a class="header-anchor" href="#right-click-menu" aria-label="Permalink to &quot;Right-click menu&quot;">​</a></h3><p><strong>Right click in the viewport</strong> to open AcesMotion&#39;s menu at the pointer. It takes a click, not a drag: a right drag still turns the camera.</p><h4 id="on-a-part" tabindex="-1">On a part <a class="header-anchor" href="#on-a-part" aria-label="Permalink to &quot;On a part&quot;">​</a></h4><p>It picks the part first, as a left click would, then offers:</p><ul><li><strong>Key</strong> (<kbd>K</kbd>).</li><li><strong>Delete keys here</strong>: the picked joints&#39; keys on the playhead.</li><li><strong>Select keys</strong>: at the playhead, or all of its keys.</li><li><strong>Reset to rest</strong>.</li><li><strong>Pick the joint above</strong> (<kbd>[</kbd>) / <strong>Pick the joint below</strong> (<kbd>]</kbd>).</li><li><strong>Copy pose</strong>, <strong>Paste pose</strong>, <strong>Paste mirrored</strong>, <strong>Flip pose</strong>, <strong>Select mirror</strong>.</li><li><strong>Pin</strong> (<strong>Unpin</strong> when every picked part is pinned).</li><li><strong>Attach to...</strong>, <strong>Detach</strong>, <strong>Back to rig</strong>.</li><li><strong>Show in Inspector</strong>.</li><li><strong>Add</strong>: Add constraint, Add Motion Warp, Add generator and Add driver, the same lists as the row menus. They go on every picked part (and every selected row) in one undo step.</li></ul><h4 id="on-empty-space" tabindex="-1">On empty space <a class="header-anchor" href="#on-empty-space" aria-label="Permalink to &quot;On empty space&quot;">​</a></h4><p><strong>Paste pose</strong>, <strong>Clear pins</strong> and <strong>Let go of the picked joints</strong>.</p><h4 id="using-the-menu" tabindex="-1">Using the menu <a class="header-anchor" href="#using-the-menu" aria-label="Permalink to &quot;Using the menu&quot;">​</a></h4><ul><li>A greyed item&#39;s click says why in the viewport&#39;s status line (&quot;No key on the playhead for the picked joints.&quot;).</li><li><kbd>Esc</kbd>, arrows and <kbd>Enter</kbd> work as in the Timeline&#39;s menus.</li></ul>',9)),i(e,{name:"fig-viewport-menu",caption:"The viewport menu on a picked part."}),t[6]||(t[6]=o('<h3 id="tween-slider" tabindex="-1">Tween slider <a class="header-anchor" href="#tween-slider" aria-label="Permalink to &quot;Tween slider&quot;">​</a></h3><p>Makes in-between poses. With the playhead between two keys, each picked joint blends between its own previous and next key.</p><ul><li>With no joint picked, every keyed joint of the selected actors blends. The root blends only when it&#39;s picked.</li><li>Letting go writes <strong>Breakdown</strong> keys at the playhead on them, in one undo step.</li><li>A joint with no key on one side is left alone.</li></ul><h4 id="modes" tabindex="-1">Modes <a class="header-anchor" href="#modes" aria-label="Permalink to &quot;Modes&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Mode</th><th>Range</th><th>What it does</th></tr></thead><tbody><tr><td><strong>Tween</strong></td><td>-50% to 150%</td><td>0% is the previous key&#39;s pose, 100% the next key&#39;s. Past the ends gives overshoot and anticipation. It rests at 50%.</td></tr><tr><td><strong>Blend to neighbour</strong></td><td>-150% to 150%</td><td>From the pose now toward the previous key to the left, or the next key to the right.</td></tr><tr><td><strong>Push / pull</strong></td><td>-150% to 150%</td><td>Away from the in-between the two keys make to the right, toward it to the left.</td></tr></tbody></table><p>The <strong>Pose menu &gt; Tween slider</strong> picks the mode and says how to start it.</p><h4 id="in-the-timeline-toolbar" tabindex="-1">In the Timeline toolbar <a class="header-anchor" href="#in-the-timeline-toolbar" aria-label="Permalink to &quot;In the Timeline toolbar&quot;">​</a></h4><p>The <strong>Tween</strong> group sits after Pins and mirror: the mode dropdown and a slider that rests at the mode&#39;s middle.</p><ul><li>Drag it: the pose follows live and a bubble reads the value.</li><li>Let go to key it, and the slider springs back.</li><li><kbd>Ctrl</kbd> snaps to 10%. <kbd>Esc</kbd> cancels.</li><li>It&#39;s the third group to go into More when the toolbar is narrow (More &gt; Tween mode).</li></ul><h4 id="in-the-viewport" tabindex="-1">In the viewport <a class="header-anchor" href="#in-the-viewport" aria-label="Permalink to &quot;In the viewport&quot;">​</a></h4><p>Press <kbd>Shift+T</kbd> (no need to hold it), then move the mouse left or right. A chip by the pointer reads &quot;Tween 70%&quot; and the two keys (&quot;f10 to f20&quot;).</p><table tabindex="0"><thead><tr><th>Key</th><th>Action</th></tr></thead><tbody><tr><td>Click or <kbd>Enter</kbd></td><td>Keeps it.</td></tr><tr><td><kbd>Esc</kbd> or a right click</td><td>Cancels.</td></tr><tr><td><kbd>Shift</kbd></td><td>Finer.</td></tr><tr><td><kbd>Ctrl</kbd></td><td>Snaps to 10%.</td></tr><tr><td>Typed digits</td><td>Set the value. <kbd>-</kbd> flips it, <kbd>Backspace</kbd> edits.</td></tr><tr><td><kbd>Tab</kbd></td><td>Changes the mode.</td></tr></tbody></table><h3 id="mirror-and-pose-tools" tabindex="-1">Mirror and pose tools <a class="header-anchor" href="#mirror-and-pose-tools" aria-label="Permalink to &quot;Mirror and pose tools&quot;">​</a></h3><p>Mirror posing writes both sides at once. The pose tools copy, paste, flip and reset poses.</p><h4 id="mirror-posing" tabindex="-1">Mirror posing <a class="header-anchor" href="#mirror-posing" aria-label="Permalink to &quot;Mirror posing&quot;">​</a></h4><p>Turn it on with the toolbar Mirror button, <kbd>Shift+M</kbd> or the Pose menu.</p><ul><li>Every joint a drag writes also writes its mirror partner, mirrored (unless you are posing both sides). Pins solve after it.</li><li>The partner of the dragged, hovered or last picked part gets a ring and a &quot;Mirror&quot; chip.</li><li>The status line reads &quot;Mirror posing | {partner} follows {joint}, mirrored | {key} turns it off&quot;.</li><li>Partners come from the <strong>mirror rules</strong> (Settings &gt; Posing): the scene&#39;s rules first, then yours.</li><li>The mirror plane is per scene (X by default; Mirror options menu).</li></ul><h4 id="pose-tools" tabindex="-1">Pose tools <a class="header-anchor" href="#pose-tools" aria-label="Permalink to &quot;Pose tools&quot;">​</a></h4><p>They&#39;re in the Pose menu, and the keys work with the viewport focused. They act on the picked joints, else the whole selected rig. The root is never copied.</p><table tabindex="0"><thead><tr><th>Tool</th><th>Key</th><th>What it does</th></tr></thead><tbody><tr><td><strong>Copy pose</strong></td><td><kbd>Shift+C</kbd></td><td></td></tr><tr><td><strong>Paste pose</strong></td><td><kbd>Shift+V</kbd></td><td>Onto the same parts, or just the picked ones.</td></tr><tr><td><strong>Paste mirrored</strong></td><td><kbd>Shift+N</kbd></td><td>Onto each part&#39;s partner, mirrored.</td></tr><tr><td><strong>Flip pose</strong></td><td><kbd>Shift+F</kbd></td><td>The pose mirrored onto the other side in place, centre joints onto themselves. Also a toolbar button.</td></tr><tr><td><strong>Select mirror</strong></td><td>Menu only</td><td>Picks each picked part&#39;s partner instead.</td></tr><tr><td><strong>Reset to rest</strong></td><td><kbd>Shift+R</kbd></td><td></td></tr></tbody></table><ul><li>A paste or reset is an unkeyed pose (keyed when Auto-key is on) and one undo step.</li><li>Over the Timeline the same keys (<kbd>Shift+C</kbd>, <kbd>Shift+V</kbd>, <kbd>Shift+N</kbd>) are the key commands instead.</li><li><kbd>Shift+F</kbd>, <kbd>Shift+R</kbd> and Select mirror work with any AcesMotion window focused too: the Timeline, Hub or the Inspector.</li><li>With the Timeline focused and keys on joint rows selected, the pose tools (and the pose slots and Quick pose) work on those keys&#39; joints at the playhead. A selected joint row works like a picked part.</li></ul><h4 id="several-actors-1" tabindex="-1">Several actors <a class="header-anchor" href="#several-actors-1" aria-label="Permalink to &quot;Several actors&quot;">​</a></h4><ul><li>Paste pose, Paste mirrored, Flip pose and Reset to rest work on the picked parts of every actor at once (or on each selected rig), in one undo step.</li><li>Copy pose holds one actor&#39;s pose. With parts picked on two actors it says so instead.</li><li>Pasting a whole copied pose onto a rig without some of its joints skips those and a toast names them.</li><li>Copy pose, Flip pose, Save pose to the library and a pose blend read the pose as keyed (and posed), not as constraints show it: a locked foot copies its keys, not the lock&#39;s hold.</li></ul><h4 id="limb-sizes" tabindex="-1">Limb sizes <a class="header-anchor" href="#limb-sizes" aria-label="Permalink to &quot;Limb sizes&quot;">​</a></h4><ul><li>Copy pose and Save pose also keep the size of every limb that has been resized (a size key or a posed size). Limbs nobody resized carry nothing, so a paste never adds size keys you didn&#39;t ask for.</li><li>Paste pose puts each size back on the same limb, Paste mirrored and Flip pose on the partner limb, in the same undo step as the pose. A pose blend from the library moves sizes part way too.</li><li>A size only lands on a part. Bones have no size, so they take the pose alone.</li><li>Poses saved before limb sizes existed apply as before.</li></ul>',25)),i(e,{name:"fig-pose-menu",caption:"The Pose menu with Mirror posing on."}),t[7]||(t[7]=o('<h3 id="attaching" tabindex="-1">Attaching <a class="header-anchor" href="#attaching" aria-label="Permalink to &quot;Attaching&quot;">​</a></h3><p>Make one thing follow another with Attach to..., and let it go with Detach or Back to rig.</p><h4 id="commands" tabindex="-1">Commands <a class="header-anchor" href="#commands" aria-label="Permalink to &quot;Commands&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Command</th><th>Key</th><th>Where</th></tr></thead><tbody><tr><td><strong>Attach to...</strong></td><td><kbd>Shift+G</kbd></td><td>Pose menu, also the actor row menus</td></tr><tr><td><strong>Detach</strong></td><td><kbd>Shift+Alt+G</kbd></td><td>Pose menu</td></tr><tr><td><strong>Back to rig</strong></td><td><kbd>Shift+Alt+A</kbd></td><td>Pose menu</td></tr><tr><td><strong>Back to rig where it is</strong></td><td>No default key</td><td>Pose menu</td></tr></tbody></table><h4 id="attach-to" tabindex="-1">Attach to... <a class="header-anchor" href="#attach-to" aria-label="Permalink to &quot;Attach to...&quot;">​</a></h4><ol><li>Pick a part, an actor, a rig joint or a skinned rig&#39;s bone (its child bones follow it). Several at once work.</li><li>Press Attach to....</li><li>Click what it should follow: another actor, or any part, attachment or bone inside one, including the same rig&#39;s own parts (move a sword from the right hand to the left hand). An Explorer selection works as the click too.</li></ol><ul><li>An Attach key goes in at the playhead, in one undo step.</li><li>The status line says &quot;Sword follows Attacker · LeftHand from f20&quot;.</li><li>Nothing jumps: it follows from where it is at that frame.</li><li>While you pick, the gizmo hides, and the part under the pointer lights up in its actor&#39;s colour with a dashed line from the object to it.</li><li>The hint names it: &quot;Sword follows r2 · RightHand. Click to attach, Esc or right click cancels.&quot;</li><li>A part it can&#39;t follow shows red with the reason.</li></ul><p><strong>The grip is saved</strong> when you attach. From then on the target carries the object on every frame, the attach frame included, so re-posing or re-keying the hand moves the sword with it.</p><ul><li>Dragging an Attach key to another frame keeps the grip (the object may jump into the hand there).</li><li>Changing the key&#39;s target takes the grip again.</li><li><strong>Hand-offs</strong>: an Attach key while already attached moves it to the new target from where it is, without a jump.</li><li><strong>Its own keys still apply</strong> while attached, riding with the target. Pose it (gizmo, IK, pins) and key it as usual, and it stays where you put it, relative to what it follows.</li></ul><p><strong>What it acts on</strong>, in order:</p><ol><li>What you selected in the Explorer inside the cast: a part (its joint, or its actor), a bone, a stand-in.</li><li>The picked joints.</li><li>The selected actors.</li></ol><p>Every click in the viewport clears stand-in parts from the Explorer selection, so the Explorer only counts when it&#39;s your latest choice.</p><h4 id="moves-by-swappable-designs" tabindex="-1">Moves by (swappable designs) <a class="header-anchor" href="#moves-by-swappable-designs" aria-label="Permalink to &quot;Moves by (swappable designs)&quot;">​</a></h4><ul><li>Select a part of a Model actor in the Explorer (an invisible <code>HolderPart</code> the other parts are welded to, say) and press Attach to.... The actor now moves by that part: &quot;Sword now moves by HolderPart.&quot;</li><li>Its keys don&#39;t change and nothing moves.</li><li>Any model that plays the role in a game (or as its stand-in) is placed so its own part of the same name lands where this one&#39;s would.</li><li>Animate one basic sword, then swap in other designs with a <code>HolderPart</code> in the same place in their hierarchy.</li><li>A model without that part moves by its pivot, with a warning in the output.</li><li>Change it or go back to the pivot in the Inspector&#39;s Attached group.</li><li>A single part actor always moves by its own pivot.</li></ul><h4 id="detach" tabindex="-1">Detach <a class="header-anchor" href="#detach" aria-label="Permalink to &quot;Detach&quot;">​</a></h4><ul><li>Puts a Detach key at the playhead for each picked object attached there, or each picked rig joint sitting on its rig.</li><li>Select an R6 arm and Detach: the torso no longer moves it. Its Motor6D stays, and Back to rig or Back to rig where it is brings it back.</li><li>It stays where it was in the scene: a dropped sword stays on the floor while the rig walks away.</li><li>The spot is saved when the key is made, so posing or keying the hand on the Detach frame (or anywhere after) no longer moves it.</li><li>Greyed with the reason when nothing picked is attached, or on its rig, at the playhead. An actor that follows nothing has nothing to let go of.</li></ul><h4 id="back-to-rig" tabindex="-1">Back to rig <a class="header-anchor" href="#back-to-rig" aria-label="Permalink to &quot;Back to rig&quot;">​</a></h4><p>For rig joints and bones only: a body part, a prop on a Motor6D in the hand, a bone. It ends an attach or a detach.</p><table tabindex="0"><thead><tr><th>Command</th><th>What it does</th></tr></thead><tbody><tr><td><strong>Back to rig</strong></td><td>Snaps it back into its place on the rig, at once or eased over the key&#39;s <strong>Blend</strong> (a thrown sword flying back into the hand).</td></tr><tr><td><strong>Back to rig where it is</strong></td><td>Rejoins its rig keeping its place in the world, and moves with the rig from there.</td></tr></tbody></table><ul><li>The key&#39;s Reattach switch in the Inspector flips between them.</li><li>A <strong>temporary detach</strong> is Detach, then Back to rig. While detached the joint keeps its Motor6D or bone, but the rig moving no longer moves it.</li><li>An actor (a part or model, like a Cup or a Sword model) has no rig to go back to. It only attaches and detaches, and Detach leaves it floating where it was.</li></ul><div class="warning custom-block"><p class="custom-block-title">Loops and missing targets</p><ul><li>Something can&#39;t follow itself or anything it carries (the status line says so).</li><li>A target that is gone (role not cast, part deleted) holds it where it was at the key.</li><li>Two objects following each other in a loop: that attachment is ignored.</li></ul></div><h4 id="ik-through-held-objects" tabindex="-1">IK through held objects <a class="header-anchor" href="#ik-through-held-objects" aria-label="Permalink to &quot;IK through held objects&quot;">​</a></h4><p>With IK on (the FK | IK switch, or <kbd>X</kbd>), dragging something a hand holds moves the arm instead. That covers a sword on a Motor6D in the hand, or anything attached with an Attach key to a rig&#39;s part or bone (a prop, another rig&#39;s joint).</p><ul><li>The object stays rigid in the hand. The arm bends (Chain field, pins and mirror posing as when you drag the hand) and only the arm is keyed.</li><li>Move handles and view drags move it. Rotate handles turn it about its own pivot (or <kbd>Tab</kbd>&#39;s temporary pivot).</li><li>An R6 arm (one joint) turns at the shoulder: a move swings the grabbed point toward the pointer, a rotate gives the sword the exact angle.</li><li>Past the arm&#39;s reach the sword stops short (&quot;Out of reach: Sword stops short.&quot;).</li><li>Several held objects picked: each moves its own arm.</li><li><strong>FK adjusts the grip</strong>: in FK (<kbd>X</kbd> switches) the same drag moves the object within the hand, keyed relative to it.</li><li>A held object whose hand is pinned doesn&#39;t move (&quot;RightHand is pinned. Unpin it, or use FK...&quot;).</li><li>One held by something that can&#39;t bend (an actor&#39;s root, a prop, a part no joint moves) moves within it, and the status says so.</li><li>The IK chain shows on the arm while you hover or drag the held object, and the hint reads &quot;IK · RightHand, holding Sword&quot;.</li><li><strong>Held objects move their holder</strong> (on by default) in the IK menu and Settings &gt; Posing turns it off. Then IK drags move the object within its hand.</li></ul><p><strong>Which joints are held props</strong>:</p><ul><li>On rigs with a Humanoid, any joint whose part isn&#39;t a body part (Roblox&#39;s own check, R15 and R6) counts automatically.</li><li>Except what hangs straight from the torso, which is always the body. A custom R6 rig&#39;s LeftArm or RightLeg, named without the space, stays a limb.</li><li>The Inspector&#39;s <strong>Held object</strong> switch on a joint sets it by hand (custom and skinned rigs, or to override).</li><li>A part held by a Weld already picks its hand, so dragging it moves the arm.</li></ul><h4 id="attach-lines" tabindex="-1">Attach lines <a class="header-anchor" href="#attach-lines" aria-label="Permalink to &quot;Attach lines&quot;">​</a></h4><ul><li>A dashed line in the target actor&#39;s colour from each attached object to the point it follows, with a dot on the target.</li><li>View &gt; Show attach lines (also Settings &gt; Posing) shows them for everything attached. Off, only the picked ones show theirs.</li></ul><h4 id="in-roblox-animations" tabindex="-1">In Roblox animations <a class="header-anchor" href="#in-roblox-animations" aria-label="Permalink to &quot;In Roblox animations&quot;">​</a></h4><ul><li>An attached joint of the exported rig is baked into the animation where the scene shows it, bones included, and so are its detaches and returns.</li><li>A prop needs a Motor6D to its hand for that; a Weld can&#39;t be animated.</li><li>A target on another actor bakes from where that actor stands in the scene, and the export notes say so.</li><li>Attached props (part or model actors) play through the AcesMotion runtime.</li></ul><h3 id="onion-skin" tabindex="-1">Onion skin <a class="header-anchor" href="#onion-skin" aria-label="Permalink to &quot;Onion skin&quot;">​</a></h3><p><strong>Ghosts</strong> are see-through tinted copies of the selected actors: red before the playhead, blue after. <kbd>Ctrl+Shift+O</kbd> toggles onion skin.</p><h4 id="ghosts" tabindex="-1">Ghosts <a class="header-anchor" href="#ghosts" aria-label="Permalink to &quot;Ghosts&quot;">​</a></h4><ul><li>Colours and falloffs are in Settings &gt; Onion.</li><li>Each further ghost is fainter by the side&#39;s falloff. A lone ghost fades too.</li><li>They hide during playback and come back on stop.</li><li>Past ghosts / Future ghosts can be turned off separately.</li></ul><h4 id="where-ghosts-stand" tabindex="-1">Where ghosts stand <a class="header-anchor" href="#where-ghosts-stand" aria-label="Permalink to &quot;Where ghosts stand&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Keys selected in the Timeline</th><th>Ghosts</th></tr></thead><tbody><tr><td>2 or more</td><td>A path is drawn from the first selected key to the last, and a ghost stands on every selected key.</td></tr><tr><td>Fewer</td><td>Ghosts sit at the nearest keys around the playhead (<strong>Ghosts at keys</strong>, &quot;Before&quot; and &quot;After&quot; counts) or every N frames (<strong>Ghosts every N frames</strong>, Step).</td></tr></tbody></table><p>With fewer keys, ghosts show for the selected actors only, unless that is off.</p><h4 id="limbs-only" tabindex="-1">Limbs only <a class="header-anchor" href="#limbs-only" aria-label="Permalink to &quot;Limbs only&quot;">​</a></h4><ul><li>Shows just the parts carried by the joints with selected keys (else the picked ones) and everything below them.</li><li>A root or nothing picked shows the whole body.</li><li>Skinned meshes cannot be split.</li></ul>',39)),i(e,{name:"viewport",caption:"Onion skin ghosts and the motion trail following the playhead."}),t[8]||(t[8]=o('<h3 id="motion-trails" tabindex="-1">Motion trails <a class="header-anchor" href="#motion-trails" aria-label="Permalink to &quot;Motion trails&quot;">​</a></h3><p>The trajectory: the path a part or root takes through the scene, drawn in the viewport and editable there.</p><h4 id="what-s-drawn" tabindex="-1">What&#39;s drawn <a class="header-anchor" href="#what-s-drawn" aria-label="Permalink to &quot;What&#39;s drawn&quot;">​</a></h4><ul><li>With 2 or more keys selected, <strong>one path</strong> is drawn through them, with a tick on every frame and a dot on every selected key.</li><li>When keys are on several parts it&#39;s a combined path through the average of those parts.</li><li>With fewer, it&#39;s the last picked part&#39;s path over Settings &gt; Trajectory &gt; Range (the Timeline&#39;s visible range or the loop region).</li><li>A root traces its pivot, a part its centre.</li><li>Up to 600 samples across all paths.</li><li>The path is a solid tube in the accent colour, faint where a part covers it.</li><li><strong>Hovering the line</strong> turns that path yellow and thicker, with a marker where it would be grabbed.</li><li>A limb keyed only on rotation cannot stretch: its path stays on a sphere round its joint.</li></ul><h4 id="editing" tabindex="-1">Editing <a class="header-anchor" href="#editing" aria-label="Permalink to &quot;Editing&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Edit with</th><th>How it works</th></tr></thead><tbody><tr><td><strong>Gizmo</strong> (default)</td><td>Click a key dot to pick it: the playhead goes to its frame and the part is picked. The pose gizmo there edits it, keyed.</td></tr><tr><td><strong>Drag</strong></td><td>Drags dots, handles and the line directly.</td></tr></tbody></table><p>Switch with Trajectory menu &gt; Edit with.</p><ul><li>With Gizmo, click a tangent handle or the line (it takes a click within 7 px) to pick it and move it with move handles only.</li><li>A point on the line also shows rings. Turning a ring bends the pose in between keys with no key (one undo step on release).</li><li><kbd>Esc</kbd> drops the pick.</li><li>The picked part&#39;s own key dot at the playhead sits under the gizmo&#39;s centre. A press there drags the gizmo, so a root on a key frame still moves from its centre.</li><li>Clicking a key dot also selects that part&#39;s keys on that frame, so Del, E and the Inspector act on them.</li><li><strong>Shift+click</strong> a key dot deletes them (one undo step).</li></ul><p>The picked key dot (the active key) shows two diamond <strong>tangent handles</strong>, each on its own line from the dot.</p><table tabindex="0"><thead><tr><th>Gesture</th><th>Does</th></tr></thead><tbody><tr><td><strong>Drag the line</strong></td><td>Bends it through the pointer with no new key.</td></tr><tr><td><strong>Double click the line</strong></td><td>Adds a key there. Every part of a combined path gets a key.</td></tr><tr><td>Drag a <strong>tangent handle</strong></td><td>Reshapes how the path leaves or arrives. Both stay smooth.</td></tr><tr><td><kbd>Alt</kbd>-drag a tangent handle</td><td>One side moves alone.</td></tr></tbody></table><h4 id="timing-mode" tabindex="-1">Timing mode <a class="header-anchor" href="#timing-mode" aria-label="Permalink to &quot;Timing mode&quot;">​</a></h4><p>Turn it on with the toolbar Timing button, or hold <kbd>J</kbd>.</p><ul><li>Dots turn hollow rings.</li><li>Drag a dot along the path to move its key earlier or later: whole frames, never past the neighbouring dots.</li><li>A chip reads &quot;f 42 · 6 earlier&quot;.</li><li>Selected keys on that frame move together.</li></ul><h4 id="display" tabindex="-1">Display <a class="header-anchor" href="#display" aria-label="Permalink to &quot;Display&quot;">​</a></h4><ul><li>Line thickness and Point size scale the path, ticks, dots, handles and their hit reach (Trajectory menu, Settings &gt; Trajectory).</li><li>Key dots, Frame ticks and the whole trajectory can be turned off.</li><li><strong>Around the playhead</strong> shows the path a set reach either side of the playhead and follows it as you scrub, so a long scene&#39;s trail stays readable.</li><li><strong>While you pose</strong>, the stretch of the trail near the playhead follows every frame, and the rest of it catches up a few times a second. Letting go redraws it exactly.</li><li>Posing stays smooth with long or sparsely keyed scenes and in IK.</li></ul>',15)),i(e,{name:"technique-trail",caption:"A motion trail with a tick per frame and a dot per key."}),t[9]||(t[9]=o('<h3 id="looking-through-a-camera" tabindex="-1">Looking through a camera <a class="header-anchor" href="#looking-through-a-camera" aria-label="Permalink to &quot;Looking through a camera&quot;">​</a></h3><p><strong>Look-through</strong> shows the scene through a camera actor. It needs a camera actor that isn&#39;t muted.</p><p>Turn it on with <kbd>Q</kbd> in the viewport or the Timeline, the toolbar camera button, the camera menu, View &gt; Camera, or the &quot;...&quot; menu when Display is in it.</p><ul><li>Studio&#39;s camera is saved: its CFrame, field of view, camera type and focus.</li><li>The camera actor&#39;s posed CFrame and FieldOfView are written to the view every frame, so scrubbing and playing film through it.</li></ul><h4 id="which-camera" tabindex="-1">Which camera <a class="header-anchor" href="#which-camera" aria-label="Permalink to &quot;Which camera&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Follow camera track</th><th>Camera shown</th></tr></thead><tbody><tr><td><strong>On</strong> (default, Settings &gt; Camera)</td><td>The camera the Camera track picks at the playhead. Cuts at switch keys are instant, and a key&#39;s Blend glides between the two cameras as in a game.</td></tr><tr><td>Off</td><td>The chosen camera: picked in the camera menu (which turns Follow off), set by an Inspector Look through button, or the camera actor you last selected while looking through.</td></tr></tbody></table><h4 id="the-chip" tabindex="-1">The chip <a class="header-anchor" href="#the-chip" aria-label="Permalink to &quot;The chip&quot;">​</a></h4><p>A chip at the top of the viewport says what is going on, with the camera icon in its key cap.</p><table tabindex="0"><thead><tr><th>Chip</th><th>When</th></tr></thead><tbody><tr><td>&quot;Looking through CloseUp, Q exits&quot;</td><td>Locked on the camera, with a thin accent frame round the viewport.</td></tr><tr><td>&quot;Looking away from CloseUp, Scrub or play to return&quot;</td><td>Looking away.</td></tr><tr><td>&quot;Look-through ended, You moved the view. Q looks through again&quot;</td><td>For 3 seconds.</td></tr><tr><td>&quot;No camera here, The next shot starts at f30&quot; (or &quot;No more shots&quot; after the last one)</td><td>In a gap. The accent frame hides.</td></tr></tbody></table><h4 id="gaps-with-no-camera" tabindex="-1">Gaps with no camera <a class="header-anchor" href="#gaps-with-no-camera" aria-label="Permalink to &quot;Gaps with no camera&quot;">​</a></h4><p>Where the Camera track has no live camera (before the first switch key, or after a shot&#39;s Until until the next key), look-through stays on but the viewport shows <strong>your own view</strong>.</p><ul><li>That&#39;s the view saved when you started looking through, then wherever you left it in the last gap.</li><li>Nothing is written there and you can move the view freely. It never counts as a view move.</li><li>When the playhead enters a shot the view locks onto the camera (your view is remembered first).</li><li>Leaving look-through in a gap keeps the view.</li><li>With Follow off the chosen camera always shows (no gaps).</li></ul><p><strong>A chosen camera lets go outside its shots.</strong> With Follow camera track off and a camera picked in the camera menu or with the Inspector&#39;s Look through:</p><ul><li>When that camera has shots on the Camera track and the playhead is outside all of them, the view lets go as in a gap (your own view, &quot;No camera here&quot;).</li><li>Back inside one of its shots it locks on again.</li><li>A camera with no shot of its own is looked through everywhere (to frame a new camera).</li></ul><p><strong>Stay on a camera between shots</strong> (Studio only; Settings &gt; Camera, the camera menu and View &gt; Camera; off by default): look-through never lets go.</p><ul><li>Where no shot is live it keeps showing the last shot&#39;s camera. Before the first switch, it shows the first shot&#39;s camera.</li><li>A chosen camera stays on outside its shots.</li><li>Games always follow the Camera track.</li></ul><h4 id="when-you-move-the-view" tabindex="-1">When you move the view <a class="header-anchor" href="#when-you-move-the-view" aria-label="Permalink to &quot;When you move the view&quot;">​</a></h4><p>Set it in the camera menu submenu or Settings &gt; Camera.</p><table tabindex="0"><thead><tr><th>Option</th><th>What happens</th></tr></thead><tbody><tr><td><strong>Look away until scrubbed or played</strong> (default)</td><td>While paused, moving the view (right drag, wheel, fly keys, focus, another plugin) lets go of the camera. Look-through stays on: the button stays lit, the frame goes. Scrubbing, playing, stepping a frame or jumping to a key snaps the view straight back. While playing, view moves are ignored.</td></tr><tr><td><strong>Exit look-through</strong></td><td>The first move leaves look-through and keeps the view where you put it.</td></tr><tr><td><strong>Stay on the camera</strong></td><td>Moves are ignored.</td></tr></tbody></table><h4 id="leaving" tabindex="-1">Leaving <a class="header-anchor" href="#leaving" aria-label="Permalink to &quot;Leaving&quot;">​</a></h4><ul><li><kbd>Q</kbd> (from either state), the button, the menu item, closing the scene or opening another, hiding the Timeline.</li><li>Leaving while locked on the camera puts Studio&#39;s view back exactly as it was.</li><li>Leaving while looking away keeps the view you moved to.</li><li>If the last camera actor is deleted, look-through ends.</li><li>Studio flies its own view down while <kbd>Q</kbd> is held in the viewport. So while the look-through key is held (up to 1 second) the view it left is held still and nothing counts as a view move: leaving with <kbd>Q</kbd> lands exactly on your saved view.</li></ul><h4 id="align-camera-to-view" tabindex="-1">Align camera to view <a class="header-anchor" href="#align-camera-to-view" aria-label="Permalink to &quot;Align camera to view&quot;">​</a></h4><p><kbd>Shift+Q</kbd> in the viewport or the Timeline, the camera menu, or the Inspector&#39;s Align to view.</p><ul><li>Moves the selected camera actor (else the live one) to your view and keys its root and FieldOfView at the playhead, in one undo step.</li><li>Refused while the view is locked on the camera. The reason shows in the Timeline status bar.</li><li>In a gap with no camera selected it says &quot;No camera is live here. Select a camera actor first.&quot;</li></ul><div class="info custom-block"><p class="custom-block-title">Undo</p><p>Camera writes never enter undo. Undo and redo keep working while looking through.</p></div><h4 id="pilot-camera" tabindex="-1">Pilot camera <a class="header-anchor" href="#pilot-camera" aria-label="Permalink to &quot;Pilot camera&quot;">​</a></h4><p><kbd>Ctrl+Shift+Q</kbd> in the viewport or the Timeline, &quot;Pilot camera&quot; in the camera menu and View &gt; Camera, or the Settings &gt; Camera toggle.</p><p>Fly Studio&#39;s view (right drag, wheel, fly keys) while looking through a camera and the camera actor itself follows, root and FieldOfView, so you can animate it by flying.</p><ul><li>Turning it on while not looking through starts looking through first. Turning it off keeps looking through.</li><li>It turns off when look-through ends or the scene closes.</li><li>It&#39;s never saved: off each time the plugin starts.</li><li>Across cuts it pilots whichever camera is live.</li><li>In a gap pilot stays on and does nothing (the view is yours there).</li><li><kbd>F</kbd> and <kbd>Ctrl+F</kbd> turn the piloted camera.</li><li>The press of <kbd>Ctrl+Shift+Q</kbd> holds the view still like <kbd>Q</kbd>, so it never counts as a move.</li></ul><h5 id="safety-and-undo" tabindex="-1">Safety and undo <a class="header-anchor" href="#safety-and-undo" aria-label="Permalink to &quot;Safety and undo&quot;">​</a></h5><ul><li>Moves count only while playback is stopped and the playhead is still.</li><li>While playing, scrubbing, stepping or dragging the playhead, view moves are ignored and the camera follows its animation. Nothing is written.</li><li><strong>One undo step per move</strong> (&quot;Pilot CloseUp&quot;), committed when the move settles: when the mouse button comes up, or after 0.3 s with no movement (keyboard flying, the wheel).</li><li>The move shows live in between, as an unkeyed pose.</li></ul><h5 id="keys" tabindex="-1">Keys <a class="header-anchor" href="#keys" aria-label="Permalink to &quot;Keys&quot;">​</a></h5><p><strong>Pilot keys</strong> is in the camera menu submenu and Settings &gt; Camera.</p><table tabindex="0"><thead><tr><th>Option</th><th>What happens</th></tr></thead><tbody><tr><td><strong>With auto-key</strong> (default)</td><td>With auto-key on, a settled move keys root and FieldOfView at the playhead. With auto-key off it stays a temporary pose (K keys it, moving the playhead drops it).</td></tr><tr><td><strong>Only with K</strong></td><td>Moves are never keyed by themselves.</td></tr></tbody></table><h5 id="while-piloting" tabindex="-1">While piloting <a class="header-anchor" href="#while-piloting" aria-label="Permalink to &quot;While piloting&quot;">​</a></h5><ul><li>The chip turns amber: &quot;Piloting CloseUp, Moves key at f40&quot; (or &quot;Moves are not keyed. K keys them&quot;).</li><li>The frame round the viewport turns amber.</li><li>&quot;When you move the view&quot; is greyed in the camera menu. It keeps its value for after.</li></ul><h5 id="refused" tabindex="-1">Refused <a class="header-anchor" href="#refused" aria-label="Permalink to &quot;Refused&quot;">​</a></h5><p>The reason shows in the Timeline status bar for 3 s, and the Settings toggle&#39;s tooltip shows it too.</p><table tabindex="0"><thead><tr><th>Cause</th><th>Reason shown</th></tr></thead><tbody><tr><td>No live camera</td><td>&quot;Pilot needs a live camera. Move the playhead into a shot, or add a camera.&quot;</td></tr><tr><td>A locked camera actor or root track</td><td>&quot;Unlock CloseUp to pilot it.&quot;</td></tr><tr><td>A muted chosen camera</td><td>&quot;Unmute CloseUp to pilot it.&quot;</td></tr><tr><td>A read-only scene</td><td></td></tr></tbody></table><p>A camera that gets locked while piloting turns pilot off with the same reason.</p>',40)),i(e,{name:"feature-camera",caption:"Looking through the scene's cameras as it plays."})])}const k=a(l,[["render",h]]);export{b as __pageData,k as default};
